class Solution {
        public int minimumMoves(int[][] grid) {
                List<int[]> zeros = new ArrayList<>();
                        List<int[]> extras = new ArrayList<>();
                                
                                        // Collect coordinates of empty cells and extra stones
                                                for (int i = 0; i < 3; i++) {
                                                            for (int j = 0; j < 3; j++) {
                                                                            if (grid[i][j] == 0) {
                                                                                                zeros.add(new int[]{i, j});
                                                                                                                } else if (grid[i][j] > 1) {
                                                                                                                                    // Add the coordinate for every extra stone
                                                                                                                                                        for (int k = 1; k < grid[i][j]; k++) {
                                                                                                                                                                                extras.add(new int[]{i, j});
                                                                                                                                                                                                    }
                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                        return backtrack(0, zeros, extras, new boolean[extras.size()]);
                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                    private int backtrack(int index, List<int[]> zeros, List<int[]> extras, boolean[] used) {
                                                                                                                                                                                                                                                                            if (index == zeros.size()) {
                                                                                                                                                                                                                                                                                        return 0;
                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                int minMoves = Integer.MAX_VALUE;
                                                                                                                                                                                                                                                                                                                        int[] zero = zeros.get(index);
                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                        // Try to match the current zero with any available extra stone
                                                                                                                                                                                                                                                                                                                                                for (int i = 0; i < extras.size(); i++) {
                                                                                                                                                                                                                                                                                                                                                            if (!used[i]) {
                                                                                                                                                                                                                                                                                                                                                                            used[i] = true;
                                                                                                                                                                                                                                                                                                                                                                                            int[] extra = extras.get(i);
                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                            int dist = Math.abs(zero[0] - extra[0]) + Math.abs(zero[1] - extra[1]);
                                                                                                                                                                                                                                                                                                                                                                                                                                            int nextMoves = backtrack(index + 1, zeros, extras, used);
                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (nextMoves != Integer.MAX_VALUE) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                minMoves = Math.min(minMoves, dist + nextMoves);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                used[i] = false; // backtrack
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return minMoves;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
